Refactor this monolithic React component to separate data fetching logic into a custom hook and improve performance by memoizing the child component.
```jsx
function Dashboard() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/data').then(r => r.json()).then(d => {
      setData(d);
      setLoading(false);
    });
  }, []);

  return (
    <div>
      {loading ? <p>Loading...</p> : data.map(item => <ListItem key={item.id} item={item} />)}
    </div>
  );
}

function ListItem({ item }) {
  console.log('Rendering ListItem');
  return <div>{item.name}</div>;
}
```

Here is the refactored code. I've extracted the data fetching logic into a custom hook `useDashboardData` and memoized the `ListItem` component using `React.memo` to prevent unnecessary re-renders.

```jsx
import React, { useState, useEffect, useMemo } from 'react';

// 1. Custom Hook for data fetching
function useDashboardData() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    fetch('/api/data')
      .then((r) => r.json())
      .then((d) => {
        if (isMounted) {
          setData(d);
          setLoading(false);
        }
      })
      .catch((err) => {
        if (isMounted) {
          setLoading(false);
          console.error(err);
        }
      });

    return () => {
      isMounted = false;
    };
  }, []);

  return { data, loading };
}

// 2. Memoized Child Component
const ListItem = React.memo(function ListItem({ item }) {
  return <div>{item.name}</div>;
});

// 3. Main Dashboard Component
function Dashboard() {
  const { data, loading } = useDashboardData();

  if (loading) {
    return <p>Loading...</p>;
  }

  return (
    <div>
      {data.map((item) => (
        <ListItem key={item.id} item={item} />
      ))}
    </div>
  );
}

export default Dashboard;
```
